	public void ApplyBackground()
	{
		try
		{
			if (settings != null && settings.Background && !string.IsNullOrEmpty(settings.BackgroundPath) && File.Exists(settings.BackgroundPath))
			{
				_bgEnabled = true;
				if (_gifTimer != null)
				{
					_gifTimer.Stop();
					_gifTimer.Dispose();
					_gifTimer = null;
				}
				if (_originalBgImage != null && ImageAnimator.CanAnimate(_originalBgImage))
				{
					ImageAnimator.StopAnimate(_originalBgImage, OnGridBackgroundFrameChanged);
				}
				if (_scaledBgCache != null)
				{
					_scaledBgCache.Dispose();
				}
				if (_originalBgImage != null)
				{
					_originalBgImage.Dispose();
				}
				if (_gifFramesCache != null)
				{
					foreach (Image item in _gifFramesCache)
					{
						item?.Dispose();
					}
					_gifFramesCache.Clear();
					_gifFramesCache = null;
				}
				_gifFrameDelays = null;
				_originalBgImage = Image.FromFile(settings.BackgroundPath);
				if (ImageAnimator.CanAnimate(_originalBgImage))
				{
					PreprocessGifFrames();
				}
				else if (GridClients.ClientSize.Width > 0 && GridClients.ClientSize.Height > 0)
				{
					_scaledBgCache = new Bitmap(GridClients.ClientSize.Width, GridClients.ClientSize.Height);
					using Graphics g = Graphics.FromImage(_scaledBgCache);
					g.InterpolationMode = InterpolationMode.HighQualityBicubic;
					g.SmoothingMode = SmoothingMode.HighQuality;
					g.PixelOffsetMode = PixelOffsetMode.HighQuality;
					g.CompositingQuality = CompositingQuality.HighQuality;
					g.DrawImage(_originalBgImage, 0, 0, GridClients.ClientSize.Width, GridClients.ClientSize.Height);
				}
				GridClients.Invalidate();
				return;
			}
			_bgEnabled = false;
			if (_gifTimer != null)
			{
				_gifTimer.Stop();
				_gifTimer.Dispose();
				_gifTimer = null;
			}
			if (_originalBgImage != null && ImageAnimator.CanAnimate(_originalBgImage))
			{
				ImageAnimator.StopAnimate(_originalBgImage, OnGridBackgroundFrameChanged);
			}
			if (_scaledBgCache != null)
			{
				_scaledBgCache.Dispose();
				_scaledBgCache = null;
			}
			if (_originalBgImage != null)
			{
				_originalBgImage.Dispose();
				_originalBgImage = null;
			}
			if (_gifFramesCache != null)
			{
				foreach (Image item2 in _gifFramesCache)
				{
					item2?.Dispose();
				}
				_gifFramesCache.Clear();
				_gifFramesCache = null;
			}
			_gifFrameDelays = null;
			GridClients.Invalidate();
		}
		catch (Exception)
		{
		}
	}

	private void PreprocessGifFrames()
	{
		try
		{
			if (_originalBgImage == null || GridClients.ClientSize.Width <= 0 || GridClients.ClientSize.Height <= 0)
			{
				return;
			}
			_gifFramesCache = new List<Image>();
			_currentGifFrame = 0;
			FrameDimension dimension = new FrameDimension(_originalBgImage.FrameDimensionsList[0]);
			int frameCount = _originalBgImage.GetFrameCount(dimension);
			_gifFrameDelays = new int[frameCount];
			try
			{
				byte[] times = _originalBgImage.GetPropertyItem(20736).Value;
				for (int i = 0; i < frameCount; i++)
				{
					int delay = BitConverter.ToInt32(times, i * 4) * 10;
					if (delay < 20)
					{
						delay = 100;
					}
					_gifFrameDelays[i] = delay;
				}
			}
			catch
			{
				for (int j = 0; j < frameCount; j++)
				{
					_gifFrameDelays[j] = 100;
				}
			}
			for (int k = 0; k < frameCount; k++)
			{
				_originalBgImage.SelectActiveFrame(dimension, k);
				Bitmap frameCopy = new Bitmap(_originalBgImage);
				Bitmap scaled = new Bitmap(GridClients.ClientSize.Width, GridClients.ClientSize.Height);
				using (Graphics g = Graphics.FromImage(scaled))
				{
					g.InterpolationMode = InterpolationMode.HighQualityBicubic;
					g.SmoothingMode = SmoothingMode.HighQuality;
					g.PixelOffsetMode = PixelOffsetMode.HighQuality;
					g.CompositingQuality = CompositingQuality.HighQuality;
					g.DrawImage(frameCopy, 0, 0, GridClients.ClientSize.Width, GridClients.ClientSize.Height);
				}
				_gifFramesCache.Add(scaled);
				frameCopy.Dispose();
			}
			if (_gifFramesCache.Count > 0)
			{
				_scaledBgCache = _gifFramesCache[0];
			}
			_gifTimer = new System.Windows.Forms.Timer();
			_gifTimer.Interval = _gifFrameDelays[0];
			_gifTimer.Tick += GifTimer_Tick;
			_gifTimer.Start();
		}
		catch (Exception)
		{
		}
	}

	private void GifTimer_Tick(object sender, EventArgs e)
	{
		try
		{
			if (_gifFramesCache != null && _gifFramesCache.Count > 0 && _gifFrameDelays != null)
			{
				_currentGifFrame = (_currentGifFrame + 1) % _gifFramesCache.Count;
				_scaledBgCache = _gifFramesCache[_currentGifFrame];
				_gifTimer.Interval = _gifFrameDelays[_currentGifFrame];
				GridClients.Invalidate();
			}
		}
		catch
		{
		}
	}

	private void RescaleBackground()
	{
		try
		{
			if (_originalBgImage == null || GridClients.ClientSize.Width <= 0 || GridClients.ClientSize.Height <= 0)
			{
				return;
			}
			if (_gifFramesCache != null && _gifFramesCache.Count > 0)
			{
				RescaleGifFrames();
				return;
			}
			if (_scaledBgCache != null)
			{
				_scaledBgCache.Dispose();
			}
			_scaledBgCache = new Bitmap(GridClients.ClientSize.Width, GridClients.ClientSize.Height);
			using (Graphics g = Graphics.FromImage(_scaledBgCache))
			{
				g.InterpolationMode = InterpolationMode.HighQualityBicubic;
				g.SmoothingMode = SmoothingMode.HighQuality;
				g.PixelOffsetMode = PixelOffsetMode.HighQuality;
				g.CompositingQuality = CompositingQuality.HighQuality;
				g.DrawImage(_originalBgImage, 0, 0, GridClients.ClientSize.Width, GridClients.ClientSize.Height);
			}
			using Graphics g2 = Graphics.FromImage(_scaledBgCache);
			g2.InterpolationMode = InterpolationMode.HighQualityBicubic;
			g2.SmoothingMode = SmoothingMode.HighQuality;
			g2.PixelOffsetMode = PixelOffsetMode.HighQuality;
			g2.CompositingQuality = CompositingQuality.HighQuality;
			g2.DrawImage(_originalBgImage, 0, 0, GridClients.ClientSize.Width, GridClients.ClientSize.Height);
		}
		catch
		{
		}
	}

	private void RescaleGifFrames()
	{
		try
		{
			if (_originalBgImage == null || _gifFramesCache == null || GridClients.ClientSize.Width <= 0 || GridClients.ClientSize.Height <= 0)
			{
				return;
			}
			bool wasRunning = false;
			if (_gifTimer != null && _gifTimer.Enabled)
			{
				wasRunning = true;
				_gifTimer.Stop();
			}
			foreach (Image frame in _gifFramesCache)
			{
				if (frame != null && frame != _scaledBgCache)
				{
					frame.Dispose();
				}
			}
			_gifFramesCache.Clear();
			FrameDimension dimension = new FrameDimension(_originalBgImage.FrameDimensionsList[0]);
			int frameCount = _originalBgImage.GetFrameCount(dimension);
			for (int i = 0; i < frameCount; i++)
			{
				_originalBgImage.SelectActiveFrame(dimension, i);
				Bitmap frameCopy = new Bitmap(_originalBgImage);
				Bitmap scaled = new Bitmap(GridClients.ClientSize.Width, GridClients.ClientSize.Height);
				using (Graphics g = Graphics.FromImage(scaled))
				{
					g.InterpolationMode = InterpolationMode.HighQualityBicubic;
					g.SmoothingMode = SmoothingMode.HighQuality;
					g.PixelOffsetMode = PixelOffsetMode.HighQuality;
					g.CompositingQuality = CompositingQuality.HighQuality;
					g.DrawImage(frameCopy, 0, 0, GridClients.ClientSize.Width, GridClients.ClientSize.Height);
				}
				_gifFramesCache.Add(scaled);
				frameCopy.Dispose();
			}
			if (_currentGifFrame >= _gifFramesCache.Count)
			{
				_currentGifFrame = 0;
			}
			_scaledBgCache = _gifFramesCache[_currentGifFrame];
			if (wasRunning && _gifTimer != null)
			{
				_gifTimer.Start();
			}
		}
		catch
		{
		}
	}

