	private void GridClients_CellPainting(object sender, DataGridViewCellPaintingEventArgs e)
	{
		if (e.RowIndex == -1 && e.ColumnIndex >= 0)
		{
			e.AdvancedBorderStyle.Left = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Right = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Bottom = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Top = DataGridViewAdvancedCellBorderStyle.None;
		}
		else if (e.RowIndex >= 0 && e.ColumnIndex >= 0)
		{
			e.AdvancedBorderStyle.Left = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Right = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Bottom = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Top = DataGridViewAdvancedCellBorderStyle.None;
		}
		if (!_bgEnabled || _scaledBgCache == null || e.RowIndex < 0 || e.ColumnIndex < 0)
		{
			return;
		}
		try
		{
			Graphics g = e.Graphics;
			g.DrawImage(_scaledBgCache, e.CellBounds, e.CellBounds.X, e.CellBounds.Y, e.CellBounds.Width, e.CellBounds.Height, GraphicsUnit.Pixel);
			float opacity = ((settings != null) ? ((float)settings.BackgroundOpacity / 100f) : 1f);
			using (SolidBrush brush = new SolidBrush(Color.FromArgb((int)((1f - opacity) * 255f), 0, 0, 0)))
			{
				g.FillRectangle(brush, e.CellBounds);
			}
			if (e.State.HasFlag(DataGridViewElementStates.Selected))
			{
				Color primary = FormMaterial.PrimaryColor;
				using (SolidBrush brush2 = new SolidBrush(Color.FromArgb(100, primary)))
				{
					g.FillRectangle(brush2, e.CellBounds);
				}
				e.CellStyle.SelectionForeColor = Color.White;
			}
			e.Paint(e.ClipBounds, DataGridViewPaintParts.Border | DataGridViewPaintParts.ContentForeground | DataGridViewPaintParts.Focus);
			e.Handled = true;
		}
		catch
		{
		}
	}

	private void GridClients_Paint(object sender, PaintEventArgs e)
	{
		if (!_bgEnabled || _scaledBgCache == null)
		{
			return;
		}
		try
		{
			DataGridView grid = GridClients;
			int header = (grid.ColumnHeadersVisible ? grid.ColumnHeadersHeight : 0);
			int lastRowBottom = header;
			if (grid.Rows.Count > 0)
			{
				int lastVisibleRow = grid.Rows.GetLastRow(DataGridViewElementStates.Visible);
				if (lastVisibleRow != -1)
				{
					lastRowBottom = grid.GetRowDisplayRectangle(lastVisibleRow, cutOverflow: true).Bottom;
				}
			}
			if (lastRowBottom < grid.ClientSize.Height)
			{
				Rectangle emptyArea = new Rectangle(0, Math.Max(header, lastRowBottom), grid.ClientSize.Width, grid.ClientSize.Height - Math.Max(header, lastRowBottom));
				e.Graphics.DrawImage(_scaledBgCache, emptyArea, emptyArea.X, emptyArea.Y, emptyArea.Width, emptyArea.Height, GraphicsUnit.Pixel);
				float opacity = ((settings != null) ? ((float)settings.BackgroundOpacity / 100f) : 1f);
				using SolidBrush brush = new SolidBrush(Color.FromArgb((int)((1f - opacity) * 255f), 0, 0, 0));
				e.Graphics.FillRectangle(brush, emptyArea);
				return;
			}
		}
		catch
		{
		}
	}

