	private void SetTransparent(Control parent)
	{
		foreach (Control c in parent.Controls)
		{
			if (c is Panel || c is TabPage || c is GroupBox || c is Label || c is CheckBox)
			{
				c.BackColor = Color.Transparent;
			}
			if (c.HasChildren)
			{
				SetTransparent(c);
			}
		}
	}

	private void ResetTransparent(Control parent)
	{
		Color back = ((MaterialSkinManager.Instance.Theme == MaterialSkinManager.Themes.DARK) ? Color.FromArgb(40, 40, 40) : Color.White);
		foreach (Control c in parent.Controls)
		{
			if (c is Panel || c is TabPage || c is GroupBox)
			{
				c.BackColor = back;
			}
			if (c.HasChildren)
			{
				ResetTransparent(c);
			}
		}
	}

	private Image BlurImage(Image image, int blurSize)
	{
		Bitmap blurred = new Bitmap(image.Width, image.Height);
		using (Graphics g = Graphics.FromImage(blurred))
		{
			g.SmoothingMode = SmoothingMode.HighQuality;
			g.InterpolationMode = InterpolationMode.HighQualityBicubic;
			g.PixelOffsetMode = PixelOffsetMode.HighQuality;
			g.DrawImage(image, new Rectangle(0, 0, blurred.Width, blurred.Height));
		}
		int sw = image.Width / Math.Max(2, blurSize);
		int sh = image.Height / Math.Max(2, blurSize);
		if (sw < 1)
		{
			sw = 1;
		}
		if (sh < 1)
		{
			sh = 1;
		}
		Bitmap small = new Bitmap(sw, sh);
		using (Graphics g2 = Graphics.FromImage(small))
		{
			g2.InterpolationMode = InterpolationMode.Bicubic;
			g2.DrawImage(image, 0, 0, sw, sh);
		}
		Bitmap final = new Bitmap(image.Width, image.Height);
		using (Graphics g3 = Graphics.FromImage(final))
		{
			g3.InterpolationMode = InterpolationMode.Bicubic;
			g3.DrawImage(small, 0, 0, image.Width, image.Height);
		}
		small.Dispose();
		blurred.Dispose();
		return final;
	}

	private Image BlurImageFast(Image image, int blurSize)
	{
		int sw = image.Width / Math.Max(2, blurSize);
		int sh = image.Height / Math.Max(2, blurSize);
		if (sw < 1)
		{
			sw = 1;
		}
		if (sh < 1)
		{
			sh = 1;
		}
		Bitmap small = new Bitmap(sw, sh);
		using (Graphics g = Graphics.FromImage(small))
		{
			g.InterpolationMode = InterpolationMode.Low;
			g.CompositingQuality = CompositingQuality.HighSpeed;
			g.SmoothingMode = SmoothingMode.HighSpeed;
			g.DrawImage(image, 0, 0, sw, sh);
		}
		Bitmap final = new Bitmap(image.Width, image.Height);
		using (Graphics g2 = Graphics.FromImage(final))
		{
			g2.InterpolationMode = InterpolationMode.Low;
			g2.CompositingQuality = CompositingQuality.HighSpeed;
			g2.SmoothingMode = SmoothingMode.HighSpeed;
			g2.DrawImage(small, 0, 0, image.Width, image.Height);
		}
		small.Dispose();
		return final;
	}

