	private void ChangeScheme(object sender)
	{
		Color primary = FormMaterial.PrimaryColor;
		bool isDark = MaterialSkinManager.Instance.Theme == MaterialSkinManager.Themes.DARK;
		ApplyThemeRecursive(this, isDark);
		BackColor = (isDark ? Color.FromArgb(40, 40, 40) : Color.White);
		if (GridClients.ColumnHeadersDefaultCellStyle != null)
		{
			if (isDark)
			{
				GridClients.ColumnHeadersDefaultCellStyle.BackColor = Color.FromArgb(40, 40, 40);
				GridClients.ColumnHeadersDefaultCellStyle.SelectionBackColor = Color.FromArgb(40, 40, 40);
			}
			else
			{
				GridClients.ColumnHeadersDefaultCellStyle.BackColor = Color.White;
				GridClients.ColumnHeadersDefaultCellStyle.SelectionBackColor = Color.White;
			}
			GridClients.ColumnHeadersDefaultCellStyle.ForeColor = primary;
			GridClients.ColumnHeadersDefaultCellStyle.SelectionForeColor = primary;
		}
		if (isDark)
		{
			GridClients.BackgroundColor = Color.FromArgb(40, 40, 40);
		}
		else
		{
			GridClients.BackgroundColor = Color.White;
		}
		if (GridClients.DefaultCellStyle != null)
		{
			if (isDark)
			{
				GridClients.DefaultCellStyle.BackColor = Color.FromArgb(40, 40, 40);
				GridClients.DefaultCellStyle.ForeColor = primary;
				GridClients.DefaultCellStyle.SelectionBackColor = primary;
				GridClients.DefaultCellStyle.SelectionForeColor = Color.White;
			}
			else
			{
				GridClients.DefaultCellStyle.BackColor = Color.White;
				GridClients.DefaultCellStyle.ForeColor = primary;
				GridClients.DefaultCellStyle.SelectionBackColor = primary;
				GridClients.DefaultCellStyle.SelectionForeColor = Color.White;
			}
		}
		foreach (DataGridViewRow item in (IEnumerable)GridClients.Rows)
		{
			item.DefaultCellStyle.ForeColor = primary;
			item.DefaultCellStyle.BackColor = (isDark ? Color.FromArgb(40, 40, 40) : Color.White);
			item.DefaultCellStyle.SelectionForeColor = Color.White;
			item.DefaultCellStyle.SelectionBackColor = primary;
		}
		GridClients.Invalidate();
		GridClients.Refresh();
		if (GridLogs.ColumnHeadersDefaultCellStyle != null)
		{
			GridLogs.ColumnHeadersDefaultCellStyle.ForeColor = primary;
			GridLogs.ColumnHeadersDefaultCellStyle.SelectionForeColor = GridLogs.ColumnHeadersDefaultCellStyle.ForeColor;
			GridLogs.ColumnHeadersDefaultCellStyle.SelectionBackColor = GridLogs.ColumnHeadersDefaultCellStyle.BackColor;
		}
		if (GridLogs.DefaultCellStyle != null)
		{
			GridLogs.DefaultCellStyle.SelectionBackColor = primary;
			GridLogs.DefaultCellStyle.SelectionForeColor = Color.White;
		}
		foreach (DataGridViewRow item2 in (IEnumerable)GridLogs.Rows)
		{
			item2.DefaultCellStyle.SelectionForeColor = Color.White;
			item2.DefaultCellStyle.SelectionBackColor = primary;
		}
		if (GridLogs.AlternatingRowsDefaultCellStyle != null)
		{
			GridLogs.AlternatingRowsDefaultCellStyle.SelectionBackColor = primary;
			GridLogs.AlternatingRowsDefaultCellStyle.SelectionForeColor = Color.White;
		}
		if (dataGridView2.ColumnHeadersDefaultCellStyle != null)
		{
			dataGridView2.ColumnHeadersDefaultCellStyle.ForeColor = primary;
			dataGridView2.ColumnHeadersDefaultCellStyle.SelectionForeColor = primary;
		}
		if (dataGridView2.DefaultCellStyle != null)
		{
			dataGridView2.DefaultCellStyle.SelectionBackColor = primary;
			dataGridView2.DefaultCellStyle.ForeColor = primary;
		}
		if (GridOfflineClients != null)
		{
			ApplyGridScheme(GridOfflineClients, primary, isDark);
		}
		if (GridTotalClients != null)
		{
			ApplyGridScheme(GridTotalClients, primary, isDark);
		}
	}

	private void ApplyGridScheme(DataGridView grid, Color primary, bool isDark)
	{
		Color back = (isDark ? Color.FromArgb(40, 40, 40) : Color.White);
		if (grid.ColumnHeadersDefaultCellStyle != null)
		{
			grid.ColumnHeadersDefaultCellStyle.BackColor = back;
			grid.ColumnHeadersDefaultCellStyle.SelectionBackColor = back;
			grid.ColumnHeadersDefaultCellStyle.ForeColor = primary;
			grid.ColumnHeadersDefaultCellStyle.SelectionForeColor = primary;
		}
		grid.BackgroundColor = back;
		if (grid.DefaultCellStyle != null)
		{
			grid.DefaultCellStyle.BackColor = back;
			grid.DefaultCellStyle.ForeColor = primary;
			grid.DefaultCellStyle.SelectionBackColor = primary;
			grid.DefaultCellStyle.SelectionForeColor = Color.White;
		}
		if (grid.AlternatingRowsDefaultCellStyle != null)
		{
			grid.AlternatingRowsDefaultCellStyle.BackColor = back;
			grid.AlternatingRowsDefaultCellStyle.ForeColor = primary;
			grid.AlternatingRowsDefaultCellStyle.SelectionBackColor = primary;
			grid.AlternatingRowsDefaultCellStyle.SelectionForeColor = Color.White;
		}
		foreach (DataGridViewRow item in (IEnumerable)grid.Rows)
		{
			item.DefaultCellStyle.ForeColor = primary;
			item.DefaultCellStyle.BackColor = back;
			item.DefaultCellStyle.SelectionForeColor = Color.White;
			item.DefaultCellStyle.SelectionBackColor = primary;
		}
		grid.Invalidate();
		grid.Refresh();
	}

