	public void SearchClients(string searchText)
	{
		if (string.IsNullOrWhiteSpace(searchText))
		{
			foreach (DataGridViewRow item in (IEnumerable)GridClients.Rows)
			{
				item.Visible = true;
			}
			return;
		}
		searchText = searchText.ToLower();
		foreach (DataGridViewRow row in (IEnumerable)GridClients.Rows)
		{
			if (row.Tag is Clients)
			{
				bool match = false;
				if (row.Cells[1].Value != null && row.Cells[1].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[3].Value != null && row.Cells[3].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[4].Value != null && row.Cells[4].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[5].Value != null && row.Cells[5].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[6].Value != null && row.Cells[6].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[7].Value != null && row.Cells[7].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[8].Value != null && row.Cells[8].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[9].Value != null && row.Cells[9].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[10].Value != null && row.Cells[10].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[11].Value != null && row.Cells[11].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[12].Value != null && row.Cells[12].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				if (row.Cells[13].Value != null && row.Cells[13].Value.ToString().ToLower().Contains(searchText))
				{
					match = true;
				}
				row.Visible = match;
			}
		}
	}

