	private void clearToolStripMenuItem_Click(object sender, EventArgs e)
	{
		GridLogs.Rows.Clear();
	}

	private void copyToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridLogs.SelectedRows.Count == 0)
		{
			return;
		}
		try
		{
			StringBuilder logText = new StringBuilder();
			foreach (DataGridViewRow selectedRow in GridLogs.SelectedRows)
			{
				string time = selectedRow.Cells[0].Value?.ToString() ?? "";
				string ip = selectedRow.Cells[1].Value?.ToString() ?? "";
				string message = selectedRow.Cells[2].Value?.ToString() ?? "";
				logText.AppendLine("[" + time + "] " + ip + " - " + message);
			}
			Clipboard.SetText(logText.ToString().TrimEnd());
		}
		catch (Exception ex)
		{
			MessageBox.Show("Error copying log: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Hand);
		}
	}

