	private void timer1_Tick(object sender, EventArgs e)
	{
		if (string.IsNullOrEmpty(animatedFormText))
		{
			animatedFormText = "✦ LiberiumRAT ✦ | ✨ Version: 3.1 [RECODE] ✨";
		}
		switch (animationType)
		{
		case 0:
			AnimateTyping();
			break;
		case 1:
			AnimateFade();
			break;
		case 2:
			AnimateSlide();
			break;
		case 3:
			AnimateWave();
			break;
		case 4:
			AnimateRainbow();
			break;
		case 5:
			Text = animatedFormText;
			break;
		default:
			AnimateTyping();
			break;
		}
	}

	private void AnimateTyping()
	{
		if (showingStaticText)
		{
			staticTextDisplayTime++;
			if (staticTextDisplayTime >= 75)
			{
				showingStaticText = false;
				staticTextDisplayTime = 0;
				currentTextIndex = 0;
				isTextExpanding = true;
				Text = "";
			}
		}
		else if (isTextExpanding)
		{
			if (currentTextIndex < animatedFormText.Length)
			{
				currentTextIndex++;
				Text = animatedFormText.Substring(0, currentTextIndex);
			}
			else
			{
				isTextExpanding = false;
			}
		}
		else if (currentTextIndex > 0)
		{
			currentTextIndex--;
			Text = animatedFormText.Substring(0, currentTextIndex);
		}
		else
		{
			showingStaticText = true;
			staticTextDisplayTime = 0;
			if (staticTexts != null && staticTexts.Length != 0)
			{
				Text = staticTexts[currentStaticTextIndex];
				currentStaticTextIndex = (currentStaticTextIndex + 1) % staticTexts.Length;
			}
		}
	}

	private void AnimateFade()
	{
		if (showingStaticText)
		{
			staticTextDisplayTime++;
			if (staticTextDisplayTime >= 75)
			{
				showingStaticText = false;
				staticTextDisplayTime = 0;
				fadeOpacity = 0f;
				fadeIncreasing = true;
			}
			return;
		}
		if (fadeIncreasing)
		{
			fadeOpacity += 0.05f;
			if (fadeOpacity >= 1f)
			{
				fadeOpacity = 1f;
				fadeIncreasing = false;
			}
		}
		else
		{
			fadeOpacity -= 0.05f;
			if (fadeOpacity <= 0f)
			{
				fadeOpacity = 0f;
				fadeIncreasing = true;
				showingStaticText = true;
				staticTextDisplayTime = 0;
				if (staticTexts != null && staticTexts.Length != 0)
				{
					Text = staticTexts[currentStaticTextIndex];
					currentStaticTextIndex = (currentStaticTextIndex + 1) % staticTexts.Length;
				}
				return;
			}
		}
		if (fadeOpacity > 0.3f)
		{
			Text = animatedFormText;
		}
		else
		{
			Text = "";
		}
	}

	private void AnimateSlide()
	{
		if (showingStaticText)
		{
			staticTextDisplayTime++;
			if (staticTextDisplayTime >= 75)
			{
				showingStaticText = false;
				staticTextDisplayTime = 0;
				slidePosition = 0;
				isTextExpanding = true;
			}
			return;
		}
		if (isTextExpanding)
		{
			slidePosition++;
			if (slidePosition >= 20)
			{
				Text = animatedFormText;
				isTextExpanding = false;
			}
			else
			{
				string spaces = new string(' ', Math.Max(0, 20 - slidePosition));
				Text = spaces + animatedFormText;
			}
			return;
		}
		slidePosition--;
		if (slidePosition <= 0)
		{
			slidePosition = 0;
			isTextExpanding = true;
			showingStaticText = true;
			staticTextDisplayTime = 0;
			if (staticTexts != null && staticTexts.Length != 0)
			{
				Text = staticTexts[currentStaticTextIndex];
				currentStaticTextIndex = (currentStaticTextIndex + 1) % staticTexts.Length;
			}
		}
		else
		{
			Text = animatedFormText;
		}
	}

	private void AnimateWave()
	{
		if (showingStaticText)
		{
			staticTextDisplayTime++;
			if (staticTextDisplayTime >= 75)
			{
				showingStaticText = false;
				staticTextDisplayTime = 0;
				waveOffset = 0;
			}
			return;
		}
		waveOffset++;
		if (waveOffset >= animatedFormText.Length * 2 + 30)
		{
			waveOffset = 0;
			showingStaticText = true;
			staticTextDisplayTime = 0;
			if (staticTexts != null && staticTexts.Length != 0)
			{
				Text = staticTexts[currentStaticTextIndex];
				currentStaticTextIndex = (currentStaticTextIndex + 1) % staticTexts.Length;
			}
			return;
		}
		int visibleChars = waveOffset;
		if (visibleChars > animatedFormText.Length)
		{
			Text = animatedFormText;
		}
		else if (visibleChars > 0)
		{
			string result = "";
			for (int i = 0; i < animatedFormText.Length; i++)
			{
				int charDelay = i * 2;
				result = ((waveOffset < charDelay) ? (result + " ") : (result + animatedFormText[i]));
			}
			Text = result.TrimEnd();
		}
		else
		{
			Text = "";
		}
	}

	private void AnimateRainbow()
	{
		if (showingStaticText)
		{
			staticTextDisplayTime++;
			if (staticTextDisplayTime >= 75)
			{
				showingStaticText = false;
				staticTextDisplayTime = 0;
				rainbowHue = 0;
			}
			return;
		}
		rainbowHue++;
		if (rainbowHue >= 120)
		{
			rainbowHue = 0;
			showingStaticText = true;
			staticTextDisplayTime = 0;
			if (staticTexts != null && staticTexts.Length != 0)
			{
				Text = staticTexts[currentStaticTextIndex];
				currentStaticTextIndex = (currentStaticTextIndex + 1) % staticTexts.Length;
			}
			return;
		}
		string result = "";
		for (int i = 0; i < animatedFormText.Length; i++)
		{
			if ((rainbowHue + i * 3) % 12 < 9)
			{
				result += animatedFormText[i];
			}
			else if (animatedFormText[i] != ' ')
			{
				char[] rainbowChars = new char[16]
				{
					'▪', '▫', '•', '○', '●', '◘', '◙', '♦', '♣', '♠',
					'♥', '★', '☆', '✦', '✧', '✨'
				};
				result += rainbowChars[(rainbowHue + i) % rainbowChars.Length];
			}
			else
			{
				result += " ";
			}
		}
		Text = result;
	}

	public void UpdateFormText(string newText)
	{
		if (string.IsNullOrEmpty(newText))
		{
			newText = "✦ LiberiumRAT ✦ | ✨ Version: 3.1 [RECODE] ✨";
		}
		animatedFormText = newText;
		currentTextIndex = 0;
		isTextExpanding = true;
		showingStaticText = false;
		staticTextDisplayTime = 0;
		Text = "";
		UpdateStaticTextWithCustomName(newText);
	}

	private void UpdateStaticTextWithCustomName(string customName)
	{
		if (string.IsNullOrEmpty(customName))
		{
			customName = "✦ LiberiumRAT v3.1 [RECODE] ✦";
		}
		staticTexts[1] = "{NAME} - лучший ратник в сети и на рынке!".Replace("{NAME}", customName);
	}

	public void ResetFormText()
	{
		animatedFormText = "✦ LiberiumRAT ✦ | ✨ Version: 3.1 [RECODE] ✨";
		currentTextIndex = 0;
		isTextExpanding = true;
		showingStaticText = false;
		staticTextDisplayTime = 0;
		currentStaticTextIndex = 0;
		Text = "";
		UpdateStaticTextWithCustomName("✦ LiberiumRAT v3.1 [RECODE] ✦");
	}

	public void SetAnimationType(int type)
	{
		if (type < 0 || type > 5)
		{
			type = 0;
		}
		animationType = type;
		currentTextIndex = 0;
		isTextExpanding = true;
		showingStaticText = false;
		staticTextDisplayTime = 0;
		fadeOpacity = 0f;
		slidePosition = 0;
		waveOffset = 0;
		rainbowHue = 0;
		fadeIncreasing = true;
		if (type == 5)
		{
			Text = animatedFormText;
		}
		else
		{
			Text = "";
		}
	}

	public void SetAnimationSpeed(int speed)
	{
		speed = Math.Max(10, Math.Min(1000, speed));
		if (timer1 != null)
		{
			timer1.Interval = speed;
		}
		if (settings != null)
		{
			settings.FormTextAnimationSpeed = speed;
		}
	}

