			GridOfflineClients.Columns[0].Width = 70;
		}
		GridOfflineClients.RowTemplate.Height = GridOfflineClients.Columns[0].Width - 20;
	}

	private void GridOfflineClients_RowPrePaint(object sender, DataGridViewRowPrePaintEventArgs e)
	{
		GridOfflineClients.Rows[e.RowIndex].Height = GridOfflineClients.RowTemplate.Height;
	}

	private void GridOfflineClients_CellPainting(object sender, DataGridViewCellPaintingEventArgs e)
	{
		if (e.RowIndex == -1 && e.ColumnIndex >= 0)
		{
			e.AdvancedBorderStyle.Left = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Right = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Bottom = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Top = DataGridViewAdvancedCellBorderStyle.None;
		}
		else if (e.RowIndex >= 0 && e.ColumnIndex >= 0)
		{
			e.AdvancedBorderStyle.Left = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Right = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Bottom = DataGridViewAdvancedCellBorderStyle.None;
			e.AdvancedBorderStyle.Top = DataGridViewAdvancedCellBorderStyle.None;
		}
	}

